      apiSlice.util.updateQueryData('getPatients', undefined, draft => {
        const item = draft.find(p => p.id === id);
        if (item) Object.assign(item, patch);
      })
    );
    try {
      await queryFulfilled; // 2. Wait for backend
    } catch {
      patchResult.undo();   // 3. Rollback if server fails!
    }
  }
})

